using namespace std;

struct P {
    int x, y;
    P() : x(0), y(0) {}
    P(int a, int b) : x(a), y(b) {}
};

int operator -(P a, P b) {
    return abs(a.x - b.x) + abs(a.y - b.y);
}

int dp[1 << 5][5][1000];
#define INF (1 << 21)

int main() {
    int W, H;

    while (cin >> W >> H, W) {
        P s, g;
        vector<P> v[6];

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                char c;
                cin >> c;
                if (c == 'S') s = P(j, i);
                else if (c == 'G') g = P(j, i);
                else if (c != '.') v[c - '1'].emplace_back(P(j, i));
            }
        }

        fill(&dp[0][0][0], &dp[0][0][0] + (1 << 5) * 5 * 1000, INF);

        for (int i = 0; i < 5; i++) {
            for (size_t j = 0; j < v[(i + 1) % 5].size(); j++) {
                dp[(1 << i) | (1 << ((i + 1) % 5))][(i + 1) % 5][j] = s - v[(i + 1) % 5][j];
            }
        }

        for (int bit = 0; bit < (1 << 5); bit++) {
            for (int x = 0; x < 5; x++) {
                int y = (x + 1) % 5;

                for (size_t i = 0; i < v[x].size(); i++) {
                    if (dp[bit][x][i] == INF) break;

                    for (size_t j = 0; j < v[y].size(); j++) {
                        dp[bit | (1 << y)][y][j] = min(dp[bit | (1 << y)][y][j], dp[bit][x][i] + (v[x][i] - v[y][j]));
                    }
                }
            }
        }

        int ans = INF, cho = -1;

        for (int i = 0; i < 5; i++) {
            for (size_t j = 0; j < v[i].size(); j++) {
                int cst = dp[(1 << 5) - 1][i][j] + (g - v[i][j]);
                int w = (i + 1) % 5;

                if (ans >= cst) {
                    if (ans == cst) {
                        cho = min(cho, w);
                    } else {
                        cho = w;
                        ans = cst;
                    }
                }
            }
        }

